def presufop():
	for t in range(int(input())):
		n = int(input())
		a = list(map(int, input().split()))
		b = list(map(int, input().split()))
		(op1, op2) = (b[0] - a[0], 0)
		(res1, res2) = (0, 0)
		for i in range(n):
			if op1 + op2 < b[i] - a[i]:
				op2 += b[i] - a[i] - op1 - op2
			elif op1 + op2 > b[i] - a[i]:
				op1 -= op1 + op2 - (b[i] - a[i])
			if op1 < 0 or op2 > b[n - 1] - a[n - 1]:
				res1 = -1
				res2 = 0
				break
			res1 = max(res1, op1)
			res2 = max(res2, op2)
		print(res1 + res2)
